  "fastmail.fm",

  // Tuta
  "tuta.com",
  "tutanota.com",
  "tutanota.de",

  // Mailfence
  "mailfence.com",

  // Yandex
  "yandex.com",
  "yandex.ru",

  // Mail.ru
  "mail.ru",
  "bk.ru",
  "inbox.ru",
  "list.ru",

  // Naver
  "naver.com",

  // QQ
  "qq.com",

  // NetEase
  "163.com",
  "126.com",

  // Brasil
  "uol.com.br",
  "bol.com.br",
  "terra.com.br",
  "ig.com.br",
  "globo.com",
  "oi.com.br",

  // Outros
  "rediffmail.com",
  "web.de",
  "email.com",
  "posteo.de",
  "hey.com"
]);

// Domínios temporários
const disposableDomains = new Set([
  "mailinator.com",
  "tempmail.com",
  "10minutemail.com",
  "guerrillamail.com",
  "sharklasers.com",
  "yopmail.com",
  "temp-mail.org",
  "dispostable.com",
  "getnada.com",
  "maildrop.cc"
]);

function getDomain(email) {
  const index = email.lastIndexOf("@");
  return index > -1 ? email.substring(index + 1) : "";
}

const domain = getDomain(email);

let classificacao = "Domínio Corporativo";

if (!domain) {
  classificacao = "E-mail inválido";
} else if (disposableDomains.has(domain)) {
  classificacao = "Domínio Temporário";
} else if (personalDomains.has(domain)) {
  classificacao = "Domínio Pessoal";
}

return {
  email,
  dominio: domain,
  classificacao
};

